const item = $input.first().json;
const candidateName = item['Candidate Full Name'] || item.candidate_name || 'Alex Rivera';
const candidateEmail = item['Candidate Email'] || item.candidate_email || 'user@example.com';
const yearsExp = item['Years of Experience'] || item.years_of_experience || 5;
const resume = item['Resume Text / Experience Summary'] || item.resume_text || '';
const linkedin = item['LinkedIn URL'] || item.linkedin_url || 'https://linkedin.com';

const targetJobDescription = `Target Role: Senior Full-Stack AI Engineer
Required Qualifications:
- 3+ years of production experience in TypeScript, Node.js, or Python
- Hands-on experience with LangChain, Vector Databases (Pinecone/Upstash/Qdrant), and LLM Tool Calling
- Strong background in microservices, Docker, Redis caching, and API design
- Excellent written communication and leadership capabilities`;

return [{
  json: {
    candidate_name: candidateName,
    candidate_email: candidateEmail,
    years_experience: yearsExp,
    linkedin_url: linkedin,
    resume_text: resume,
    target_job_spec: targetJobDescription
  }
}];

