const evalData = $('AI Resume Evaluation').item.json.output || $('AI Resume Evaluation').item.json;
const candidate = $('Attach Job Criteria').item.json;

const strengths = Array.isArray(evalData.strengths) ? evalData.strengths : [evalData.strengths || 'Strong technical background'];
const questions = Array.isArray(evalData.tailored_interview_questions) ? evalData.tailored_interview_questions : [evalData.tailored_interview_questions || 'Describe your system architecture'];

const formattedSummary = `
⭐ **NEW HIGH-FIT CANDIDATE DETECTED (Score: ${evalData.match_score}/100)** ⭐

👤 **Candidate:** ${candidate.candidate_name} (${candidate.candidate_email})
💼 **Experience:** ${candidate.years_experience} Years
🔗 **LinkedIn:** ${candidate.linkedin_url}

📝 **Executive Summary:**
${evalData.executive_summary}

✅ **Top Strengths:**
${strengths.map(s => '• ' + s).join('\n')}

🎯 **Recommended Tailored Questions for Interviewer:**
${questions.map((q, i) => `${i+1}. ${q}`).join('\n')}

📅 **Action:** Automated invitation link dispatched to candidate.
`;

return [{
  json: {
    notification_text: formattedSummary,
    candidate_name: candidate.candidate_name,
    candidate_email: candidate.candidate_email,
    match_score: evalData.match_score,
    status: 'Interview Scheduled'
  }
}];

const evalData = $('AI Resume Evaluation').item.json.output || $('AI Resume Evaluation').item.json;
const candidate = $('Attach Job Criteria').item.json;

const gaps = Array.isArray(evalData.gaps_or_concerns) ? evalData.gaps_or_concerns : [evalData.gaps_or_concerns || 'Requires portfolio review'];

const reviewSummary = `
⚠️ **CANDIDATE REQUIRES HIRING MANAGER REVIEW (Score: ${evalData.match_score}/100)** ⚠️

👤 **Candidate:** ${candidate.candidate_name} (${candidate.candidate_email})
💼 **Experience:** ${candidate.years_experience} Years

📝 **Evaluation:**
${evalData.executive_summary}

🔍 **Identified Gaps / Concerns:**
${gaps.map(g => '• ' + g).join('\n')}

📌 **Next Step:** HR Lead must review portfolio before sending invite or rejection.
`;

return [{
  json: {
    notification_text: reviewSummary,
    candidate_name: candidate.candidate_name,
    candidate_email: candidate.candidate_email,
    match_score: evalData.match_score,
    status: 'Under Review'
  }
}];

const candidate = $('Attach Job Criteria').item.json;
