return [{
  json: {
    ats_record_id: 'ATS-' + Date.now(),
    candidate_name: candidate.candidate_name,
    candidate_email: candidate.candidate_email,
    years_experience: candidate.years_experience,
    match_score: evalData.match_score,
    recommendation: evalData.recommendation,
    executive_summary: evalData.executive_summary,
    strengths: evalData.strengths,
    gaps: evalData.gaps_or_concerns,
    interview_questions: evalData.tailored_interview_questions,
    processed_at: new Date().toISOString(),
    status: 'COMPLETED_AUTOMATICALLY'
  }
